viz(v) {
        const PRE = { ae: '∀x∃y E(x,y)', ea: '∃y∀x E(x,y)', sym: '∀x∀y (E(x,y) → E(y,x))', cyc: '∃x∃y∃z (E(x,y) ∧ E(y,z) ∧ E(z,x))' };
        const pre = v.select('sentence', [{ value: 'ae', label: '∀x∃y E' }, { value: 'ea', label: '∃y∀x E' }, { value: 'sym', label: 'symmetric' }, { value: 'cyc', label: '3-cycle' }], 'ae', { onChange: (k) => fld.set(PRE[k]) });
        const fld = foField(v, 'sentence', PRE.ae, { width: 260, sig: { name: 'the language of graphs', rels: { E: 2 }, funcs: {}, consts: [] }, check: (a) => (freeVars(a).length ? `free variable ${freeVars(a)[0]}: type a sentence` : null), onChange: () => S.reset(null, { at: 'end' }) });
        const A = v.stage({ x: [-1.45, 1.45], y: [-1.4, 1.4], equal: true, axes: false, height: 330, weight: 0.95, title: 'the structure' });
        const B = v.stage({ x: [0, 1], y: [0, 1], axes: false, height: 330, weight: 1.05, title: 'evaluation of the formula tree' });
        const E = relEditor(v, A, { n: 4, radius: 1.0, edges: [[0, 1], [1, 2], [2, 0], [3, 3], [1, 3]], onChange: () => S.reset(null, { at: 'end' }) });
        let run = null;
        const build = () => { const M = graphStruct(E.n, E.adj()); run = { M, ...traceEval(fld.ast, M, {}, { limit: 400 }) }; return run.frames; };
        const S = v.steps({ frames: build, start: 'end', still: 'end', speed: 3 });
        let Lc = null, last = null;
        v.render(() => {
          if (last !== fld.ast) { last = fld.ast; Lc = layoutFO(fld.ast); }
          const f = S.frame || {}, env = f.env || {}, vals = f.vals || new Map();
          const at = new Map(); for (const [x, d] of Object.entries(env)) at.set(d, (at.get(d) ? at.get(d) + ',' : '') + x);
          const end = S.atEnd, line = end ? explainLine(fld.ast, run.M) : [];
          const deciding = new Set(line.filter((l) => l.role !== 'all' && l.d !== undefined).map((l) => l.d));
          // at the end of a ∀x∃y (or ∃x∀y) sentence: the whole witness (counterexample) function
          const phi = fld.ast, sk = end && isQ(phi) && isQ(phi.a) && phi.op !== phi.a.op ? new Map(run.M.dom.map((d) => [d, run.M.dom.find((e) => holds(phi.a.a, run.M, { [phi.v]: d, [phi.a.v]: e }) === (phi.a.op === 'ex'))])) : null;
          E.G.draw({
            nodeRing: (id) => (E.sel === id ? 'gold' : f.trying === id && !end ? 'orange' : end && !sk && deciding.has(id) ? (run.val ? 'green' : 'red') : null),
            nodeFill: (id) => (!sk && at.has(id) ? 'gold' : null),
            nodeNote: (id) => (sk ? (sk.get(id) === undefined ? `no ${phi.a.v}` : `${phi.a.v}=${sk.get(id)}`) : at.get(id) || null),
            noteColor: (id) => (sk ? (sk.get(id) === undefined ? 'red' : phi.a.op === 'ex' ? 'green' : 'red') : 'gold'),
          });
          if (sk) A.corner(phi.a.op === 'ex' ? `witness ${phi.a.v} for each ${phi.v}` : `counterexample ${phi.a.v} for each ${phi.v}`, 'bl', { size: 11, color: phi.a.op === 'ex' ? 'green' : 'red' });
          fitFO(B, Lc, { minW: 4 });
          drawFO(B, Lc, {
            fill: (nd) => (vals.has(nd.e.id) ? (vals.get(nd.e.id) ? 'green' : 'red') : null),
            ring: (nd) => (f.node && nd.e.id === f.node.id ? 'gold' : null),
            note: (nd) => (isQ(nd.e) && env[nd.e.v] !== undefined ? `${nd.e.v}=${env[nd.e.v]}` : ''),
            noteColor: () => 'gold',
          });
          if (fld.error) B.corner(fld.error, 'bl', { color: 'red', size: 11 });
          if (run.cut) B.corner('trace shortened', 'br', { size: 10.5 });
        });
        v.legend([['gold', 'current values of the variables', { dot: true }], ['orange', 'element being tried', { dot: true }], ['green', 'true', { dot: true }], ['red', 'false', { dot: true }]]);
        v.readout(() => {
          const M = run.M, phi = fld.ast, val = holds(phi, M);
          let detail = '';
          if (isQ(phi) && isQ(phi.a) && phi.op !== phi.a.op) {
            const x = phi.v, y = phi.a.v, body = phi.a.a;
            const pick = (d) => M.dom.find((e) => holds(body, M, { [x]: d, [y]: e }) === (phi.a.op === 'ex'));
            if (phi.op === 'all' && val) detail = ` For each $${x}$ a witness $${y}$: ${M.dom.map((d) => `$${x}{=}${d} \\mapsto ${y}{=}${pick(d)}$`).join(', ')}.`;
            else if (phi.op === 'all') { const d = M.dom.find((d0) => pick(d0) === undefined); detail = ` Counterexample: $${x} = ${d}$, for which no $${y}$ works.`; }
            else if (phi.op === 'ex' && !val) detail = ` Every $${x}$ fails: ${M.dom.map((d) => `$${x}{=}${d}$ (counterexample $${y}{=}${pick(d)}$)`).join(', ')}.`;
            else { const d = M.dom.find((d0) => pick(d0) === undefined); detail = ` Witness: $${x} = ${d}$ works against every $${y}$.`; }
          } else {
            const ln = explainLine(phi, M).filter((l) => l.role !== 'all');
            if (ln.length) detail = ' Deciding choices: ' + ln.map((l) => `${l.role} $${l.x} = ${l.d}$`).join(', ') + '.';
          }
          return `$\\mathfrak A \\models ${toTex(phi)}$ is **${val ? 'TRUE' : 'FALSE'}** in this ${M.n}-element structure.${detail} Step ${S.i + 1} of ${S.n}.`;
        });
      }

viz(v) {
        const tol = v.toggle('accept tolerance premise', true);
        const nS = v.slider('grains $n$', 1, 1e6, 40, { log: true, int: true, sig: 3 });
        const P = v.stage({ x: [-20, 20], y: [-1, 19], equal: true, axes: false, height: 290, title: 'a pile of $n$ grains' });
        const L = v.stage({ x: [1, 1e6], y: [0, 1], xlog: true, axes: 'box', gutter: true, height: 290, title: 'the chain from 1 grain to $n$ grains', xlabel: 'grains', yticks: [] });
        const hC = L.handle(300, 0.22, { color: 'green', r: 8, label: 'my cut-off c', labelPos: 'n', constrain: (x) => [clampN(Math.round(x), 2, 999999), 0.22] });
        let info = {};
        v.render(() => {
          const n = Math.round(nS.value), c = Math.round(clampN(hC.x, 2, 999999));
          // pile
          const isHeap = n >= c;
          const k = Math.min(n, GRAINS.length);
          if (n > GRAINS.length) {
            const t = Math.min(1, Math.log(n / GRAINS.length) / Math.log(1e6 / GRAINS.length));
            const r = 14 + 4 * t;
            const pts = []; for (let a = 0; a <= 40; a++) { const th = Math.PI * a / 40; pts.push([r * Math.cos(th), 0.3 + 0.9 * r * Math.sin(th) * (1 - 0.0 * t)]); }
            P.poly(pts, { fill: isHeap ? 'green' : 'orange', fillAlpha: 0.12, color: isHeap ? 'green' : 'orange', width: 1.5 });
          }
          for (let i = 0; i < k; i++) P.dot(GRAINS[i][0], GRAINS[i][1] * 0.95, { r: 6, color: isHeap ? 'green' : 'orange' });
          P.line(-19, 0.0, 19, 0.0, { color: 'muted', width: 2 });
          P.corner(`${grp(n)} grain${n === 1 ? '' : 's'}${n > GRAINS.length ? ' (a 355-grain sample is drawn)' : ''}`, 'tl', { color: 'ink', weight: 'bold' });
          P.corner(isHeap ? 'by your cut-off: a heap' : 'by your cut-off: not a heap', 'tr', { color: isHeap ? 'green' : 'orange' });
          // chain
          L.rect(1, 0.06, c, 0.38, { fill: 'orange', fillAlpha: 0.14, stroke: false });
          L.rect(c, 0.06, 1e6, 0.38, { fill: 'green', fillAlpha: 0.14, stroke: false });
          L.text('not a heap (yours)', Math.sqrt(c), 0.4, { color: 'orange', size: 12, baseline: 'bottom' });
          if (c < 3e5) L.text('heap (yours)', Math.sqrt(c * 1e6), 0.4, { color: 'green', size: 12, baseline: 'bottom' });
          if (tol.value) {
            L.arrow(1, 0.72, Math.max(n, 1.0001), 0.72, { color: n >= c ? 'red' : 'blue', width: 3 });
            L.dot(1, 0.72, { r: 5, color: 'blue' }); L.text('1 grain: not a heap', 1.3, 0.62, { color: 'blue', size: 12, baseline: 'top' });
            L.dot(n, 0.72, { r: 6, color: n >= c ? 'red' : 'blue' });
            L.text(`${grp(Math.max(n - 1, 0))} steps of “not a heap ⇒ still not a heap”`, 1.3, 0.9, { color: n >= c ? 'red' : 'blue', size: 12, baseline: 'bottom', align: 'left' });
          } else {
            L.vline(c, { color: 'red', width: 2 });
            L.text('the one false instance', c, 0.62, { color: 'red', size: 12, align: 'center' });
          }
          L.vline(n, { color: 'gold', width: 2, alpha: 0.8 });
          info = { n, c, isHeap };
        });
        v.readout(() => {
          const { n, c, isHeap } = info;
          if (tol.value) {
            return n >= c
              ? `Tolerance applied ${grp(n - 1)} times from “1 grain is not a heap” proves “${grp(n)} grains are not a heap”.\nYour own verdict: ${grp(n)} ≥ ${grp(c)} is a heap. **Contradiction**: something you accepted has to go.`
              : `Tolerance applied ${grp(Math.max(n - 1, 0))} times proves “${grp(n)} grains are not a heap”, which agrees with your verdict (${grp(n)} < ${grp(c)}).\nDrag $n$ up to ${grp(c)} and beyond to see where the chain collides with your cut-off.`;
          }
          return `Without tolerance your cut-off makes the premise false at exactly one pair: ${grp(c - 1)} grains are not a heap, ${grp(c)} are.\nThen one grain makes the difference between a heap and a non-heap, which is what tolerance denied. ${isHeap ? '' : ''}`;
        });
      }
